    k, h, w = m.group(1), int(m.group(2)), int(m.group(3))
    end_pos = m.end()

    # Get grid content - search for next h lines of number data
    remaining = t[end_pos:]
    found_rows = []

    for i, line in enumerate(remaining.split('\n')):
        if i >= h:
            break
        line_stripped = line.strip()
        if '[' in line_stripped or '0' in line_stripped.split()[0] if line_stripped.split() else False:
            try:
                # Try JSON format
                if line_stripped.startswith('['):
                    cleaned = line_stripped.replace('[', '').replace(']', '')
                    row = [int(x) for x in cleaned.split(',')]
                    found_rows.append(row)
                elif line_stripped.replace(' ', '').isdigit():
                    # Space-separated format
                    row = [int(x) for x in line_stripped.split()]
                    found_rows.append(row)
